[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; uint depth; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = (float2(idx) + 0.5) / float2(dim);
    float2 ndc = uv * 2.0 - 1.0;
    ndc.y = -ndc.y;
    float aspect = float(dim.x) / float(dim.y);
    float3 dir = normalize(float3(ndc.x * aspect, ndc.y, 2.0));
    float t = time_sim_ms * 0.001;
    float3 origin = float3(sin(t * 0.3) * 2.0, 0.5, -3.0);

    RayDesc ray;
    ray.Origin = origin;
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 1);
    p.depth = 0;
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; uint depth; };
[shader("miss")]
void Miss(inout Payload p)
{
    float3 dir = WorldRayDirection();
    float sky = 0.5 + 0.5 * dir.y;
    p.c = float4(lerp(float3(0.5, 0.7, 1.0), float3(0.1, 0.2, 0.6), sky), 1.0);
}

[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; uint depth; };

[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    float3 hitPos = WorldRayOrigin() + WorldRayDirection() * RayTCurrent();
    float3 bary = float3(1.0 - a.barycentrics.x - a.barycentrics.y, a.barycentrics.x, a.barycentrics.y);
    float3 normal = normalize(float3(0, 1, 0));
    if (PrimitiveIndex() < 2) normal = float3(0, 1, 0);
    else normal = normalize(cross(float3(1,0,0), float3(0,0,1)));
    float3 baseColor = float3(0.8, 0.3, 0.2);
    float reflectivity = 0.6;
    if (p.depth < 2) {
        float3 reflDir = reflect(WorldRayDirection(), normal);
        RayDesc reflRay;
        reflRay.Origin = hitPos + normal * 0.001;
        reflRay.TMin = 0.001;
        reflRay.Direction = reflDir;
        reflRay.TMax = 100.0;
        Payload rp;
        rp.c = float4(0, 0, 0, 1);
        rp.depth = p.depth + 1;
        TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, reflRay, rp);
        p.c = float4(lerp(baseColor, rp.c.rgb, reflectivity), 1.0);
    } else {
        p.c = float4(baseColor, 1.0);
    }
}
